var t=`0132-chakhokhbili`;var n=`world-0132`;var a=`GE`;var s=`western-asia`;var o=4;var r=64;var l={en:`Chakhokhbili`,ua:`Чахохбілі`};var g={en:`A classic dish from Georgia, featuring chicken thigh, yellow onion, garlic, red bell pepper. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Грузія. Основні складники: куряче стегно, жовта цибуля, часник, червоний солодкий перець. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var h=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`chicken-thigh`,820,`g`],[`sunflower-oil`,30,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,230,`g`],[`garlic`,4,`clove`],[`red-bell-pepper`,150,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 40 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 40 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:40,i:[[`tomato`,620,`g`],[`tomato-paste`,30,`g`],[`bay-leaf`,2,`leaf`],[`sweet-paprika`,8,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,25,`g`],[`parsley`,15,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var d={slug:t,id:n,country:`GE`,region:s,servings:4,minutes:64,title:l,text:g,steps:h};export{a as country,d as default,n as id,r as minutes,s as region,o as servings,t as slug,h as steps,g as text,l as title};